            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(g[r][c] == sep for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    def occupied(r0, r1, c0, c1):
        return any(g[r][c] not in (0, sep) for r in range(r0, r1) for c in range(c0, c1))

    # Adjacent compartments containing a motif form a mirrored pair. If only
    # one compartment in a neighboring pair is occupied, reflect it into the next.
    for r0, r1 in row_bands:
        j = 0
        while j < len(col_bands) - 1:
            c0, c1 = col_bands[j]
            d0, d1 = col_bands[j + 1]
            a = occupied(r0, r1, c0, c1)
            b = occupied(r0, r1, d0, d1)
            if a and b:
                j += 2
                continue
            if a and not b:
                for rr in range(r0, r1):
                    for k in range(c1 - c0):
                        g[rr][d1 - 1 - k] = g[rr][c0 + k]
                j += 2
            elif b and not a:
                for rr in range(r0, r1):
                    for k in range(d1 - d0):
                        g[rr][c0 + k] = g[rr][d1 - 1 - k]
                j += 2
            else:
                j += 1
    return g

